 if(state.hp>0){const c=SHOT_COLOR;for(let r=52;r>24;r-=9){bg.fillStyle(c,.025);bg.fillCircle(b.coreX,b.coreY,r)}cg.fillStyle(0x071321,1);cg.fillCircle(b.coreX,b.coreY,17);cg.lineStyle(3,c,.85);cg.strokeCircle(b.coreX,b.coreY,20+Math.sin(a*4));cg.fillStyle(c,.8);{let r=13;cg.fillPoints([{x:b.coreX,y:b.coreY-r},{x:b.coreX+r,y:b.coreY},{x:b.coreX,y:b.coreY+r},{x:b.coreX-r,y:b.coreY}],true)}cg.lineStyle(1,c,.25);cg.strokeEllipse(b.x,b.y-90,190,195);for(let i=0;i<7;i++){let angle=a*.7+i*Math.PI*2/7;cg.fillStyle(c,.45);cg.fillRect(Math.round(b.x+Math.cos(angle)*100),Math.round(b.y-90+Math.sin(angle)*99),3,3)}const ac=state.attackClock%3.9;if(ac>2.1&&ac<2.72&&state.mode==='play'){g.fillStyle(c,.1+(ac-2.1)*.15);g.fillRect(0,GROUND-3,b.x-80,3);g.fillStyle(c,.65);for(let x=b.x-90;x>0;x-=34){g.fillTriangle(x,GROUND-8,x+8,GROUND-12,x+8,GROUND-4)}}}
