function segmentDistance(px,py,x1,y1,x2,y2){const dx=x2-x1,dy=y2-y1,len=dx*dx+dy*dy;const u=len?Phaser.Math.Clamp(((px-x1)*dx+(py-y1)*dy)/len,0,1):0;return Math.hypot(px-(x1+u*dx),py-(y1+u*dy))}
